def parts(n, m):
    if n == 0:
        return 1               # the empty sum: one way
    if m == 0:
        return 0               # nothing left to use, but n > 0
    if m > n:
        m = n                  # a part cannot be bigger than n
    return parts(n - m, m) + parts(n, m - 1)

