long long parts(int n, int m) {
    if (n == 0) return 1;
    if (m == 0) return 0;
    if (m > n) m = n;
    if (memo[n][m] < 0) memo[n][m] = parts(n - m, m) + parts(n, m - 1);
    return memo[n][m];
